_LOG_FORMAT = "%(asctime)s %(name)s %(levelname)s %(message)s"


def get_logger(name: str) -> logging.Logger:
    """Return a configured logger.  Handlers are attached once per process."""
    logger = logging.getLogger(name)
    if not logging.getLogger().handlers and not logger.handlers:
        handler = logging.StreamHandler(sys.stderr)
        handler.setFormatter(logging.Formatter(_LOG_FORMAT))
        logger.addHandler(handler)
        logger.setLevel(os.environ.get("LOOP_LOG_LEVEL", "INFO").upper())
    return logger


log = get_logger("loop.common")


class PolicyError(RuntimeError):
    """A policy file is missing or malformed.

    Raised instead of falling back to silent divergent defaults тА?the P0-8.3
    fix direction: policy unreadable => fail closed and visible.
    """


class ModelPinError(PolicyError):
    """A required model pin could not be resolved from configuration."""


def utc_now() -> float:
    """Wall-clock epoch seconds (single definition so tests can monkeypatch)."""
    return time.time()


# ---------------------------------------------------------------------------
# Paths тА?Windows/WSL compatible.  All joins go through pathlib; no separator
# is ever hardcoded (task constraint: cross-platform path compatibility).
# ---------------------------------------------------------------------------
@dataclass(frozen=True)
class LoopPaths:
    """Resolved directory layout for one LOOP root.

    ``root`` honours ``$LOOP_ROOT`` when constructed via :meth:`resolve`,
    falling back to the package root two levels above this file.
    """

    root: Path

    @classmethod
    def resolve(cls, root: Path | str | None = None) -> "LoopPaths":
        """Resolve the LOOP root: explicit arg > $LOOP_ROOT > package root."""
        if root is not None:
            return cls(Path(root).resolve())
        env = os.environ.get("LOOP_ROOT")
        if env:
            return cls(Path(env).resolve())
        return cls(Path(__file__).resolve().parents[1])

    # -- directories --------------------------------------------------------
    @property
    def data(self) -> Path:
        return self.root / "data"

    @property
    def config(self) -> Path:
        return self.root / "config"

    @property
    def events(self) -> Path:
        return self.data / "events.ndjson"

    @property
    def events_lock(self) -> Path:
        return self.data / "lifecycle" / ".events.lock"

    @property
    def ledger(self) -> Path:
        return self.data / "progress_ledger.json"

    @property
    def l2_queue_dir(self) -> Path:
        return self.data / "l2_queue"

    @property
    def l2_pending(self) -> Path:
        return self.l2_queue_dir / "pending.ndjsonl"

    @property
    def l2_claims_dir(self) -> Path:
        return self.l2_queue_dir / "claims"

    @property
    def l2_heartbeat(self) -> Path:
        return self.l2_queue_dir / "consumer_heartbeat.json"

    @property
    def governor_dir(self) -> Path:
        return self.data / "governor"

    @property
    def budget_dir(self) -> Path:
        return self.data / "budget"

    @property
    def router_dir(self) -> Path:
        return self.data / "router"

    @property
    def usage_dir(self) -> Path:
        return self.data / "usage"

    @property
    def refill_dir(self) -> Path:
        return self.data / "refill"

    @property
    def meter_report(self) -> Path:
        """Resolve the newest meter contract before compatibility fallbacks.

        ``model_token_share_v2.py`` writes ``model_token_share_v2.json``.
        Older F2 components used ``meter_v2_report.json`` and v1 used
        ``model_token_share.json``; keep those readable in that order without
        pointing the governor at a path that no producer writes.
        """
        candidates = (
            self.usage_dir / "model_token_share_v2.json",
            self.usage_dir / "meter_v2_report.json",
            self.usage_dir / "model_token_share.json",
        )
        return next((path for path in candidates if path.exists()), candidates[0])

    @property
    def token_ledger(self) -> Path:
        return self.usage_dir / "token_ledger.ndjsonl"

    @property
    def run_role_map(self) -> Path:
        return self.usage_dir / "run_role_map.json"


# ---------------------------------------------------------------------------
# Locking / atomic IO
# ---------------------------------------------------------------------------
@contextlib.contextmanager
def file_lock(path: Path) -> Iterator[None]:
    """Cross-process one-byte advisory lock (same protocol the shipped
    ``lifecycle_supervisor.locked`` uses, so v2 components interoperate with
    v1 writers on the same lock files)."""
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a+b") as handle:
        handle.seek(0, os.SEEK_END)
        if handle.tell() == 0:
            handle.write(b"\0")
            handle.flush()
        handle.seek(0)
        if os.name == "nt":  # pragma: no cover - Windows plane
            import msvcrt

            msvcrt.locking(handle.fileno(), msvcrt.LK_LOCK, 1)
        else:
            import fcntl

            fcntl.flock(handle.fileno(), fcntl.LOCK_EX)
        try:
            yield
        finally:
            handle.seek(0)
            if os.name == "nt":  # pragma: no cover - Windows plane
                import msvcrt

                msvcrt.locking(handle.fileno(), msvcrt.LK_UNLCK, 1)
            else:
                import fcntl

                fcntl.flock(handle.fileno(), fcntl.LOCK_UN)


def read_json(path: Path | str, default: Any = None) -> Any:
    """Read JSON, returning ``default`` on any IO/parse failure."""
    try:
        return json.loads(Path(path).read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return default


def atomic_write_json(path: Path | str, value: Any) -> None:
    """Write JSON atomically (tmp file + ``os.replace``); fsynced."""
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(f"{path.name}.{os.getpid()}.tmp")
    with tmp.open("w", encoding="utf-8", newline="\n") as handle:
        json.dump(value, handle, ensure_ascii=False, indent=2, sort_keys=True)
        handle.write("\n")
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(tmp, path)


def append_ndjson(path: Path | str, obj: Mapping[str, Any],
                  lock_path: Path | None = None) -> None:
    """Append one JSON line under an advisory lock (append-only ledger)."""
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    lock = lock_path if lock_path is not None else path.with_suffix(path.suffix + ".lock")
    with file_lock(lock):
        with path.open("a", encoding="utf-8", newline="\n") as handle:
            handle.write(json.dumps(obj, ensure_ascii=False,
                                    separators=(",", ":")) + "\n")


def iter_ndjson(path: Path | str) -> Iterator[dict[str, Any]]:
    """Yield parsed records from an NDJSON file; malformed lines are skipped
    with a warning (fail-visible via log, never a crash)."""
    path = Path(path)
    if not path.exists():
        return
    with path.open(encoding="utf-8") as handle:
        for lineno, line in enumerate(handle, 1):
            line = line.strip()
            if not line:
                continue
            try:
                rec = json.loads(line)
            except ValueError:
                log.warning("iter_ndjson: %s:%d unparseable line skipped", path, lineno)
                continue
            if isinstance(rec, dict):
                yield rec


# ---------------------------------------------------------------------------
# Semantic idempotency keys (V10 k3IdemKey pattern)
# ---------------------------------------------------------------------------
def idem_key(kind: str, scope: str, *semantic_fields: str) -> str:
    """Build ``k3:<kind>:<scope>:<b32(sha256(fields))[:16]>``.

    The key is derived from *semantic* fields (never timestamps), so the same
    logical request always maps to the same key тА?the exactly-once boundary
    for the l2 consumer and every append-only ledger record.
    """
    digest = hashlib.sha256("|".join(semantic_fields).encode("utf-8")).digest()
    suffix = base64.b32encode(digest).decode("ascii").lower().rstrip("=")[:16]
    return f"k3:{kind}:{scope}:{suffix}"


# ---------------------------------------------------------------------------
# Policy loading тА?fail-closed
# ---------------------------------------------------------------------------
def _load_toml(path: Path, what: str) -> dict[str, Any]:
    if not path.exists():
        raise PolicyError(f"{what} missing: {path} тА?refusing silent defaults "
                          f"(P0-8.3 fail-closed policy reads)")
    try:
        with path.open("rb") as handle:
            return tomllib.load(handle)
    except (OSError, tomllib.TOMLDecodeError) as exc:
        raise PolicyError(f"{what} unreadable: {path}: {exc}") from exc


@dataclass
class OrchestrationPolicy:
    """Typed view over ``config/orchestration_policy.toml``.

    Declaration face = enforcement face (design invariant 2): every limit the
    file declares is read here and enforced by the component that owns it.
    Concurrency numbers are **not** duplicated here тА?they live only in
    ``refill_policy.toml`` (invariant 3); this policy carries a
    ``refill_policy_ref`` key instead.
    """

    doc: dict[str, Any] = field(default_factory=dict)
    path: Path | None = None

    @classmethod
    def load(cls, paths: LoopPaths | None = None) -> "OrchestrationPolicy":
        paths = paths or LoopPaths.resolve()
        explicit = os.environ.get("LOOP_ORCH_POLICY")
        policy_path = (Path(explicit).resolve() if explicit
                       else paths.config / "orchestration_policy.toml")
        return cls(_load_toml(policy_path, "orchestration policy"), policy_path)

    # -- generic accessors ----------------------------------------------------
    def value(self, section: str, key: str, default: Any = None) -> Any:
        table = self.doc.get(section, {})
        return table.get(key, default) if isinstance(table, dict) else default

    def require(self, section: str, key: str) -> Any:
        value = self.value(section, key, None)
        if value is None:
            raise PolicyError(
                f"orchestration policy [{section}].{key} missing in {self.path} "
                f"тА?fail-closed (declaration face = enforcement face)")
        return value

    # -- routing ---------------------------------------------------------------
    def routing_mode(self) -> str:
        """``cold_start`` | ``shadow`` | ``layered``.

        ``passthrough_enabled`` (legacy boolean) is honoured only as an alias:
        ``false -> cold_start``, ``true -> layered``.  Missing everything =>
        cold_start (safe default, byte-identical legacy behavior).
        """
        mode = self.value("routing", "mode")
        if isinstance(mode, str) and mode in ("cold_start", "shadow", "layered"):
            return mode
        legacy = self.value("routing", "passthrough_enabled")
        if isinstance(legacy, bool):
            return "layered" if legacy else "cold_start"
        return "cold_start"

    def verify_sample_rate(self) -> float:
        value = self.value("routing", "verify_sample_rate", 0.10)
        return float(value) if isinstance(value, (int, float)) else 0.10

    # -- model pins --------------------------------------------------------------
    def model_pin(self, role_family: str) -> str:
        """Resolve the model id for a role family (``sol`` / ``k3`` / ``v4``).

        Read from ``[models]``; missing pin raises :class:`ModelPinError` тА?        silently falling back to a hardcoded model string is exactly the
        defect class being fixed (task constraint: never hardcode
        ``deepseek-v4-flash`` or any other model id in code).
        """
        models = self.doc.get("models", {})
        pin = models.get(role_family) if isinstance(models, dict) else None
        if not isinstance(pin, str) or not pin:
            raise ModelPinError(
                f"orchestration policy [models].{role_family} missing in "
                f"{self.path}; refusing to guess a model id (fail-visible)")
        return pin

    def model_context(self, role_family: str, key: str) -> int | None:
        """Optional context sizing (``context_window`` / ``compaction``)."""
        table = self.doc.get("model_context", {})
        entry = table.get(role_family) if isinstance(table, dict) else None
        value = entry.get(key) if isinstance(entry, dict) else None
        return int(value) if isinstance(value, int) and not isinstance(value, bool) else None

    # -- token bands / hysteresis ---------------------------------------------------
    def sol_hard_cap(self) -> float:
        return float(self.value("tokens", "sol_allocation_cap",
                                self.value("tokens", "sol_hard_cap", 0.15)))

    def k3_floor(self) -> float:
        return float(self.value("tokens", "k3_floor", 0.20))

    def minimum_denominator(self) -> int:
        return int(self.value("tokens", "minimum_denominator", 2_000_000))

    def hysteresis(self) -> dict[str, float]:
        return {
            "enter_high": float(self.value("hysteresis", "enter_high_sol_share", 0.25)),
            "enter_samples": int(self.value("hysteresis", "enter_samples", 2)),
            "leave_high": float(self.value("hysteresis", "leave_high_sol_share", 0.22)),
            "leave_samples": int(self.value("hysteresis", "leave_samples", 2)),
            "critical_1h_share": float(self.value("hysteresis", "critical_1h_share", 0.35)),
        }

    # -- governor bounds ---------------------------------------------------------------
    def planning_max_turns(self) -> int:
        return int(self.value("governor", "planning_max_turns", 6))

    def planning_max_new_tokens(self) -> int:
        return int(self.value("governor", "planning_max_new_tokens", 30_000))

    def l2_max_age_s(self) -> float:
        return float(self.value("routing", "l2_max_age_s", 900))


@dataclass
class RefillPolicy:
    """Typed, fail-closed view over ``config/refill_policy.toml`` тА?the ONLY
    concurrency authority (P0-8.3).  Any read failure raises
    :class:`PolicyError` instead of returning a divergent default."""

    doc: dict[str, Any] = field(default_factory=dict)
    path: Path | None = None

    @classmethod
    def load(cls, paths: LoopPaths | None = None) -> "RefillPolicy":
        paths = paths or LoopPaths.resolve()
        explicit = os.environ.get("LOOP_REFILL_POLICY")
        policy_path = (Path(explicit).resolve() if explicit
                       else paths.config / "refill_policy.toml")
        return cls(_load_toml(policy_path, "refill policy"), policy_path)

    def _int(self, section: str, key: str) -> int:
        table = self.doc.get(section, {})
        value = table.get(key) if isinstance(table, dict) else None
        if not isinstance(value, int) or isinstance(value, bool):
            raise PolicyError(f"refill policy [{section}].{key} missing/invalid "
                              f"in {self.path} тА?fail-closed, no silent default")
        return value

    def target_total(self) -> int:
        return self._int("concurrency", "target_total")           # 48

    def v4_target(self) -> int:
        return self._int("concurrency", "v4_target")              # 36

    def k3_target(self) -> int:
        return self._int("concurrency", "k3_target")              # 12

    def v4_low_water(self) -> int:
        return self._int("concurrency", "v4_low_water")

    def k3_low_water(self) -> int:
        return self._int("concurrency", "k3_low_water")

    def spawn_interval_ms(self) -> int:
        return self._int("spawn_throttle", "spawn_interval_ms")   # 1000

    def reservations_borrowable(self) -> bool:
        table = self.doc.get("concurrency", {})
        value = table.get("reservations_borrowable", True) if isinstance(table, dict) else True
        return bool(value)

    def policy_version(self) -> str:
        table = self.doc.get("meta", {})
        value = table.get("policy_version") if isinstance(table, dict) else None
        return str(value) if value is not None else "unversioned"

    def __init__(self, paths: LoopPaths | None = None,
                 policy: OrchestrationPolicy | None = None) -> None:
        self.paths = paths or LoopPaths.resolve()
        self.policy = policy or OrchestrationPolicy.load(self.paths)
        self.hysteresis = HysteresisController(self.paths,
                                               self.policy.hysteresis())

    # -- loop state ----------------------------------------------------------
    def loop_state(self) -> tuple[str, bool]:
        """Return ``(state, trusted)``.  ``trusted=False`` means the ledger
        was unreadable тА?the caller must fail closed for non-planning."""
        led = read_json(self.paths.ledger, None)
        if led is None:
            if self.paths.ledger.exists():
                return "unknown", False       # present but unreadable: fail closed
            return "planning", True           # genuinely fresh root: lease governs
        attested = _attested_state(self.paths, led)
        if attested:
            return attested, True
        states = [p.get("state") for p in led.get("packets", {}).values()]
        if not states:
            return "planning", True
        if any(s in ADJUDICATION_STATES for s in states):
            return "adjudication", True
        if all(s in TERMINAL_STATES for s in states):
            return "release_finalize", True
        # EXPAND_K3 / L2_VERIFY / L2_RANK land here: execution (┬з7).
        return "execution", True

    # -- meter --------------------------------------------------------------------
    def meter_status(self) -> tuple[float | None, str]:
        """Return ``(sol_5h_effective_share, status)`` from the meter report.

        ``status`` тИ?{OK, STALE, MISSING, MALFORMED, INSUFFICIENT_DATA}.
        STALE/MISSING/MALFORMED are fail-closed inputs for non-planning turns.
        """
        path = self.paths.meter_report
        if not path.exists():
            return None, "MISSING"
        report = read_json(path, None)
        if not isinstance(report, dict):
            return None, "MALFORMED"
        stale_after = float(self.policy.value("governor", "meter_stale_after_s",
                                              7200))
        generated = report.get("generated_at", report.get("generated_ts"))
        if generated is None:
            # A report with no timestamp cannot prove freshness.
            return None, "MALFORMED"
        try:
            if utc_now() - float(generated) > stale_after:
                return None, "STALE"
        except (TypeError, ValueError):
            return None, "MALFORMED"
        windows = report.get("windows", {})
        w5h = windows.get("rolling_5h") if isinstance(windows, dict) else None
        if not isinstance(w5h, dict):
            return None, "MALFORMED"
        if w5h.get("status") == "INSUFFICIENT_DATA":
            return None, "INSUFFICIENT_DATA"
        share = w5h.get("sol_share_effective", w5h.get("share_effective"))
        try:
            return float(share), "OK"
        except (TypeError, ValueError):
            return None, "MALFORMED"

    # -- budget integration -----------------------------------------------------------
    def budget_state(self) -> str:
        """Budget controller state for the root task (NORMAL when absent)."""
        doc = read_json(self.paths.budget_dir / "active.json", None)
        if isinstance(doc, dict):
            state = doc.get("state")
            if state in ("NORMAL", "THROTTLE", "DEGRADE", "BREAK"):
                return str(state)
        return "NORMAL"

    # -- evaluation ----------------------------------------------------------------------
    def evaluate(self, tool_name: str, model: str | None = None,
                 estimated_new_tokens: int = 0) -> GovernorDecision:
        """Evaluate one root-session tool call.  Deterministic, zero-model."""
        tool = (tool_name or "").lower()
        if not tool.startswith(GATED_TOOLS):
            return GovernorDecision(Verdict.ALLOW, "tool not gated", "-")

        # Model-family screen: dispatch-target families are never gated; an
        # unknown/absent model cannot bypass by omitting the field.
        family = self._model_family(model)
        if family in ("v4", "k3"):
            return GovernorDecision(Verdict.ALLOW, "dispatch-target family", "-")
        if family != "sol":
            return self._deny(
                "PreToolUse payload.model is missing or unknown (%r); a gated "
                "operation cannot bypass the Sol policy by omitting model"
                % (model,), "-", ("governor.fail_closed",))

        state, trusted = self.loop_state()

        # Break-glass: observable, audited, never silent.
        override = os.environ.get(BREAK_GLASS_ENV)
        if override:
            self._event("governor.break_glass",
                        {"tool": tool, "reason": override, "loop_state": state})
            return GovernorDecision(Verdict.ALLOW,
                                    f"break-glass override: {override}", state,
                                    ("governor.break_glass",))

        # Fail-closed on unreadable ledger for anything but a fresh root.
        if not trusted:
            self._event("governor.fail_closed",
                        {"tool": tool, "why": "ledger_unreadable"})
            return self._deny(
                "progress ledger unreadable тА?failing closed. Gated tools deny "
                "until the ledger is restored; packet/dispatch tools remain "
                "available (decompose and dispatch).", state,
                ("governor.fail_closed",))

        # Budget ladder (Tier 2/3 integration): DEGRADE/BREAK deny gated tools.
        budget = self.budget_state()
        if budget in ("DEGRADE", "BREAK"):
            self._event("governor.fail_closed",
                        {"tool": tool, "why": f"budget_{budget.lower()}"})
            return self._deny(
                "task budget state is %s: only adjudication/dispatch tools are "
                "allowed. Delegate: dispatch.py --role worker --packet <id> "
                "(or open a bounded adjudication packet)." % budget, state,
                ("governor.fail_closed",))

        # Planning lease (the P0-5.2 fix): bounded, renewable exemption.
        if state == "planning":
            lease = PlanningLease.load(self.paths)
            max_turns = self.policy.planning_max_turns()
            max_tokens = self.policy.planning_max_new_tokens()
            if lease.exhausted(max_turns, max_tokens):
                self._event("governor.lease_denied",
                            {"tool": tool, "turns_used": lease.turns_used,
                             "new_tokens_used": lease.new_tokens_used})
                return self._deny(
                    "decompose or dispatch: planning lease exhausted "
                    "(%d/%d turns, %d/%d new tokens) тА?emit packets/*.json + "
                    "dag.json or open an adjudication packet; packet creation "
                    "renews the lease."
                    % (lease.turns_used, max_turns,
                       lease.new_tokens_used, max_tokens), state)
            lease.consume_turn(self.paths, estimated_new_tokens)
            return GovernorDecision(Verdict.ALLOW, "planning lease", state)

        if state in ("adjudication", "release_finalize"):
            return GovernorDecision(Verdict.ALLOW, f"{state} state", state)

        # Execution (incl. K3 work states): meter-driven share enforcement.
        share, status = self.meter_status()
        if status in ("MISSING", "MALFORMED", "STALE"):
            self._event("governor.fail_closed",
                        {"tool": tool, "why": f"meter_{status.lower()}"})
            return self._deny(
                "token meter is %s тА?failing closed for non-planning Sol "
                "turns. Delegate: dispatch as a packet, or restore the meter."
                % status, state, ("governor.fail_closed",))
        if status == "OK" and share is not None:
            band = self.hysteresis.observe(
                share, sample_id=f"{self.paths.meter_report}:{share:.6f}")
            if band == "HIGH":
                self._event("governor.share_denied",
                            {"tool": tool, "share_5h": share})
                return self._deny(
                    "Sol 5h effective share %.2f%% is in the HIGH band тА?"
                    "delegate: route to k3 verifier "
                    "(dispatch.py --role verifier --packet <id>) or dispatch "
                    "the work as a V4 packet. Auto-delegation is the "
                    "reward-optimal action; this turn is refused."
                    % (share * 100), state)
        # INSUFFICIENT_DATA never actuates (denominator floor, ┬з2.4.4).
        return self._deny(
            "LOOP state is %s: this operation belongs in an L0/L1 packet "
            "(AGENTS.md ┬з2 тА?Sol rounds are for planning/adjudication). "
